[{"name": "aid_officer_permit", "definition": "// aid_officer_permit  (kind: permit  ·  validation: FAIL_ON_ANY_FINDINGS)
// A financial-aid officer may use the governed tools. Deny-by-default is automatic at the AgentCore
// Policy engine; this is the only broad grant. The principal is authorized by the Cognito group claim
// surfaced as a tag — no group, no access.
permit(principal, action, resource is AgentCore::Gateway)
when {
  principal.hasTag("cognito:groups") &&
  principal.getTag("cognito:groups") like "*aid_officer*"
};
", "validation_mode": "FAIL_ON_ANY_FINDINGS"}, {"name": "mask_before_assess", "definition": "// mask_before_assess  (kind: forbid  ·  validation: IGNORE_ALL_FINDINGS)
// No aid determination on un-masked data. assess_aid is forbidden unless the caller passes
// deidentified == true (set only by mask_pii). forbid wins over any permit.
forbid(
  principal,
  action == AgentCore::Action::"assess-aid___assess_aid",
  resource == AgentCore::Gateway::"__GATEWAY_ARN__"
)
unless { context.input.deidentified == true };
", "validation_mode": "IGNORE_ALL_FINDINGS"}, {"name": "mask_before_draft", "definition": "// mask_before_draft  (kind: forbid  ·  validation: IGNORE_ALL_FINDINGS)
// No award-notice drafting on un-masked data. draft_award_notice is forbidden unless deidentified == true,
// so the model only ever sees de-identified case text.
forbid(
  principal,
  action == AgentCore::Action::"fa-core___draft_award_notice",
  resource == AgentCore::Gateway::"__GATEWAY_ARN__"
)
unless { context.input.deidentified == true };
", "validation_mode": "IGNORE_ALL_FINDINGS"}, {"name": "mask_before_pj", "definition": "// mask_before_pj  (kind: forbid  ·  validation: IGNORE_ALL_FINDINGS)
// No professional-judgment recommendation on un-masked data. record_professional_judgment is forbidden
// unless deidentified == true (set only by mask_pii). forbid wins over any permit.
forbid(
  principal,
  action == AgentCore::Action::"record-pj___record_professional_judgment",
  resource == AgentCore::Gateway::"__GATEWAY_ARN__"
)
unless { context.input.deidentified == true };
", "validation_mode": "IGNORE_ALL_FINDINGS"}, {"name": "no_self_commit", "definition": "// no_self_commit  (kind: forbid  ·  validation: IGNORE_ALL_FINDINGS)
// The agent can never commit an award. finalize_award is forbidden outright and hidden from the agent's
// tool list; the only path to commit is the human sign-off gate (Step Functions), where a DIFFERENT
// qualified aid officer approves with a single-use token.
forbid(
  principal,
  action == AgentCore::Action::"fa-core___finalize_award",
  resource == AgentCore::Gateway::"__GATEWAY_ARN__"
);
", "validation_mode": "IGNORE_ALL_FINDINGS"}, {"name": "no_self_professional_judgment", "definition": "// no_self_professional_judgment  (kind: forbid  ·  validation: IGNORE_ALL_FINDINGS)
// Committing a Professional Judgment (HEA 479A) adjustment is a CONSEQUENTIAL, SENIOR-HUMAN-ONLY act.
// The agent can never commit a PJ; commit_professional_judgment is forbidden outright and hidden from the
// agent's tool list. Same deny-by-default pattern as no_self_commit.
forbid(
  principal,
  action == AgentCore::Action::"fa-core___commit_professional_judgment",
  resource == AgentCore::Gateway::"__GATEWAY_ARN__"
);
", "validation_mode": "IGNORE_ALL_FINDINGS"}]
